def maximum_alternating_color_triangle_height(red,blue):
    def build(first,second):
        height=0
        while True:
            needed=height+1
            if height%2==0:
                if first<needed:return height
                first-=needed
            else:
                if second<needed:return height
                second-=needed
            height+=1
    return max(build(red,blue),build(blue,red))

